window.kbPageData["views/entry/k-e9764cd121f5885b"] = {"key":"entry/k-e9764cd121f5885b","state":{"route":"entry/k-e9764cd121f5885b"},"node":{"id":"k-e9764cd121f5885b","mode":"k","title":"等腰直角三角形的判定与边长比","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2024 地市级 行测#70"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"有一个锐角为45°的直角三角形是等腰直角三角形，两条直角边与斜边的长度比为1∶1∶√2。","review":{"definition":"有一个锐角为45°的直角三角形是等腰直角三角形，两条直角边与斜边的长度比为1∶1∶√2。","explanation":"五边形内角和为540°。扣除A、C、E处的三个直角及B处的135°，可得D处的内角也是135°。延长AB和ED，从C分别向两条延长线作垂线，垂足为F和G。B、D处的外角均为45°，所以三角形BFC和DGC都是等腰直角三角形。由CD＝50米得DG＝CG＝25√2米，由BF＝FC得BC＝√2·FC。","references":[],"evidence":"为等腰直角三角形，CD=50米","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#70":{"paper":"国考 2024 地市级 行测","n":70,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",12],"asrc":["e1792c53900a45f1b9fa.pdf",21],"card":"3254bdd04bb896a20759d1a0","links":[{"id":"k-e9764cd121f5885b","role":"解题依据","why":"有一个45°锐角的直角三角形是等腰直角三角形，其两条直角边与斜边之比为1∶1∶√2，可据此换算斜边与两个方向上的长度。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e9764cd121f5885b":[["国考 2024 地市级 行测#70"]]}};
